content.content:
                    ops: { binding.ops(video: VideoPatch(cornerRadius: $0)) },
                    mixed: { binding.mixedVideo { $0.cornerRadius } })
            ])
    }

    // MARK: Chroma key

    /// The M3 green-screen group (§4.3): the switch, the key colour with its
    /// canvas eyedropper, and the three knobs the shader keys with. The core
    /// bounds all four of them to 0…1 (`props_check.rs`'s `video.chroma.*`),
    /// so the three are dialled as percentages of that range and the colour
    /// is written as the three components `chroma.key` is — the one colour in
    /// the schema with no alpha in it.
    ///
    /// Every control writes a WHOLE `ChromaProps`, exactly as the Shadow
    /// group does: the patch replaces the object, so each edit re-sends the
    /// other three values as they stand.
    ///
    /// "Pick from Canvas" stays live with the key switched OFF, and picking
    /// then turns it on: someone who has just aimed at the green has already
    /// said what they want, and making them flip a switch first to be allowed
    /// to say it is a step that carries no decision.
    func chromaSection() -> InspectorSection {
        let binding = self.binding
        func current() -> ChromaProps { binding.videoProps.chroma ?? ChromaProps() }
        func ops(_ next: ChromaProps) -> [ReelOp] {
            binding.ops(video: VideoPatch(chroma: .some(next)))
        }
        func on() -> Bool { binding.videoProps.chroma != nil }
        let pick = commandButton(
            "Pick from Canvas", #selector(EditorViewController.pickChromaKey(_:)),
            toolTip: "Click the preview to sample the key color (Esc cancels)")
        return InspectorSection(
            id: "video.chroma", title: "Chroma Key",
            summary: { on() ? String(format: "%.0f%%", current().tolerance * 100) : "off" },
            reset: { binding.apply("Chroma Key", video: VideoPatch(chroma: .some(nil))) },
            defaultExpanded: false,
            rows: [
                inspectorCheckRow(
                    "Key out a color", binding, name: "Chroma Key",
                    read: on,
                    ops: { value in
                        binding.ops(
                            video: VideoPatch(chroma: value ? .some(ChromaProps()) : .some(nil)))
                    },
                    mixed: { binding.mixedVideo { $0.chroma != nil } }),
                inspectorColorRow(
                    "Key Color", binding, name: "Chroma Key Color",
                    // Padded to four components on the way in and cut back to
                    // three on the way out: `changedRGBA`'s unchanged-colour
                    // guard compares component by component and gives up when
                    // the two lengths differ — which, with the colour panel
                    // writing continuously through a drag, would beep at every
                    // mouse-moved event that changed nothing.
                    read: { current().key + [1] },
                    ops: { color in
                        var c = current()
                        c.key = chromaKeyComponents(color)
                        return ops(c)
                    },
                    mixed: { binding.mixedVideo { $0.chroma?.key } },
                    enabled: on),
                inspectorButtonRow([pick]),
                inspectorValueRow(
                    "Tolerance", binding, name: "Chroma Tolerance", unit: "%", decimals: 0,
                    min: 0, max: 100, quick: [0, 10, 20, 40, 60],
                    read: { current().tolerance * 100 },
                    ops: { value in
                        var c = current()
                        c.tolerance = value / 100
                        return ops(c)
                    },
                    mixed: { binding.mixedVideo { $0.chroma?.tolerance } },
                    enabled: on),
                inspectorValueRow(
                    "Softness", binding, name: "Chroma Softness", unit: "%", decimals: 0,
                    min: 0, max: 100, quick: [0, 5, 10, 25, 50],
                    read: { current().softness * 100 },
                    ops: { value in
                        var c = current()
                        c.softness = value / 100
                        return ops(c)
                    },
                    mixed: { binding.mixedVideo { $0.chroma?.softness } },
                    enabled: on),
                inspectorValueRow(
                    "Spill", binding, name: "Chroma Spill", unit: "%", decimals: 0,
                    min: 0, max: 100, quick: [0, 25, 50, 75, 100],
                    read: { current().spill * 100 },
                    ops: { value in
                        var c = current()
                        c.spill = value / 100
                        return ops(c)
                    },
                    mixed: { binding.mixedVideo { $0.chroma?.spill } },
                    enabled: on),
            ])
    }

    // MARK: Filters

    /// The filter stack (§4.3's M3 list), at most `FilterProps.max` deep.
    ///
    /// **Order is the whole point.** The compositor applies `video.filters`
    /// in the order they are listed, so blur-then-sepia and sepia-then-blur
    /// are different pictures, and a control set that cannot say which comes
    /// first would be lying about what the layer does. That is why each
    /// filter's row leads with a POSITION popup rather than an ordinal label:
    /// the number both shows where the filter sits and is the thing that
    /// moves it. It occupies the label column the rest of the inspector
    /// already reserves, where a Move Up / Move Down pair costs two controls
import AppKit

/// The Picture sub-tab's Background section (road map creator-jobs CO3, spec §11 CO-30): Remove
/// Background by Vision on the Mac, right after Chroma Key. The checkbox and Reset are the
/// clip's — a base `set_video` whatever is selected, so inside an action they are ⊘ — and
/// Background, Edge and Feather write a sparse `cutoutPart`, which an action animates (an end
/// gets only the row's own key). Status reads the pane's `CutoutStatus.Memo`; Analyze Now asks
/// the editor's `analyzeCutoutNow` (the wants made again, then a failed run retried). With every
/// selected clip a picture, Subject (Person, Foreground) follows the checkbox: the clip's, like
/// it (road map creator-jobs CO10b, spec §11 CO-108).
extension VideoPane {

    /// Every selected clip can be cut out: a media or still clip of a video file with pictures,
    /// or an image clip of a picture (CO-108).
    var allCutoutable: Bool {
        let clips = binding.clips
        return !clips.isEmpty
            && clips.allSatisfy { CutoutStatus.canCutOut($0, in: binding.snapshot) }
    }

    /// Every selected clip is an image clip — the Subject row's gate (CO-108).
    var allPictures: Bool {
        let clips = binding.clips
        return !clips.isEmpty && clips.allSatisfy {
            if case .image = $0.source { return true }
            return false
        }
    }

    /// Every selected video clip has a BASE cutout — Background, Edge and Feather's gate.
    var allCutOut: Bool {
        let clips = binding.videoClips
        return !clips.isEmpty && clips.allSatisfy { $0.video?.cutout != nil }
    }

    func cutoutSection(_ memo: CutoutStatus.Memo) -> InspectorSection {
        let binding = self.binding
        func anyOn() -> Bool { binding.videoClips.contains { $0.video?.cutout != nil } }
        func allOn() -> Bool { allCutOut }
        func cut() -> CutoutProps { binding.videoProps.cutout ?? CutoutProps() }
        func onOps() -> [ReelOp] {
            binding.videoClips.filter { $0.video?.cutout == nil }.flatMap {
                binding.ops(video: VideoPatch(cutout: .some(CutoutProps())), for: $0)
            }
        }
        // Base whatever is selected: `structural(video:for:)` sends a cutout's presence there.
        func offOps() -> [ReelOp] { binding.ops(video: VideoPatch(cutout: .some(nil))) }
        func part(_ patch: CutoutPatch) -> [ReelOp] {
            binding.ops(video: VideoPatch(cutoutPart: patch))
        }
        let enabled: () -> Bool = { [weak self] in self?.allCutOut ?? false }
        func single() -> (UInt32, ProjectDocument)? {
            guard binding.videoClips.count == 1, let clip = binding.videoClips.first,
                let document = binding.document
            else { return nil }
            return (clip.id, document)
        }
        func statusWords() -> String {
            guard let (clip, document) = single() else { return "—" }
            return CutoutStatus.words(memo.status(of: clip, in: document).state)
        }
        func analyzable() -> Bool {
            guard let document = binding.document else { return false }
            let states: [CutoutState]
            if let (clip, document) = single() {
                states = [memo.status(of: clip, in: document).state]
            } else {
                states = binding.videoClips.filter { $0.video?.cutout != nil }.map {
                    CutoutStatus.status(of: $0.id, in: document).state
                }
            }
            return states.contains {
                switch $0 {
                case .analyzing, .failed: return true
                default: return false
                }
            }
        }

        let check = OptionCheckboxControl(
            label: "Remove background", read: allOn,
            write: { value in binding.apply("Remove Background", value ? onOps() : offOps()) },
            enabled: { true }, onEdit: { binding.edited() })
        weak var statusView: OptionDisplayControl?
        let readout = inspectorReadout(width: 170) {
            let words = statusWords()
            statusView?.toolTip = words
            if let statusView, let (clip, document) = single() {
                memo.watch(statusView, clip: clip, document: document)
            }
            return words
        }
        statusView = readout
        let analyze = OptionButtonControl(
            title: "Analyze Now",
            action: { [weak self] in
                self?.inspector?.onCommand?(#selector(EditorViewController.analyzeCutoutNow(_:)))
                memo.invalidate()
                binding.edited()
            },
            enabled: analyzable, onEdit: {})
        analyze.toolTip = "Make this clip's masks now, again after a failure"
        let backgrounds = CutoutBackground.allCases
        let subjects = CutoutSubject.allCases
        // The clip's subject, written whole on the BASE through `structural(video:for:)` —
        // a cutout's presence goes there, so the row is ⊘ inside an action (CO-108).
        func subjectOps(_ index: Int) -> [ReelOp] {
            guard subjects.indices.contains(index) else { return [] }
            return binding.videoClips.compactMap { clip -> [ReelOp]? in
                guard var base = clip.video?.cutout else { return nil }
                base.subject = subjects[index]
                return binding.ops(video: VideoPatch(cutout: .some(base)), for: clip)
            }.flatMap { $0 }
        }
        let subjectRow: [NSView] = allPictures
            ? [
                inspectorPopupRow(
                    "Subject", binding, name: "Cutout Subject", items: ["Person", "Foreground"],
                    read: { subjects.firstIndex(of: cut().subject) ?? 0 },
                    ops: subjectOps,
                    mixed: {
                        Set(binding.videoClips.compactMap { $0.video?.cutout?.subject }).count > 1
                    },
                    enabled: enabled)
            ] : []
        return InspectorSection(
            id: "video.cutout", title: "Background",
            summary: {
                guard anyOn() else { return "off" }
                return single() == nil ? "on" : statusWords()
            },
            reset: { binding.apply("Remove Background", offOps()) },
            defaultExpanded: false,
            rows: [
                inspectorRow(
                    nil, [check], mixed: { anyOn() && !allOn() }, binding: binding,
                    writes: offOps(),
                    default: InspectorRowDefault(
                        name: "Remove Background", differs: anyOn, ops: offOps)),
            ] + subjectRow + [
                inspectorPopupRow(
                    "Background", binding, name: "Cutout Background", items: ["Remove", "Keep"],
                    read: { backgrounds.firstIndex(of: cut().background) ?? 0 },
                    ops: { index in
                        guard backgrounds.indices.contains(index) else { return [] }
                        return part(CutoutPatch(background: backgrounds[index]))
                    },
                    mixed: { binding.mixedVideo { $0.cutout?.background } },
                    enabled: enabled),
                inspectorValueRow(
                    "Edge", binding, name: "Cutout Edge", decimals: 2, min: -1, max: 1,
                    quick: [-0.5, -0.25, 0, 0.25, 0.5],
                    read: { cut().edge },
                    ops: { part(CutoutPatch(edge: $0)) },
                    mixed: { binding.mixedVideo { $0.cutout?.edge } },
                    enabled: enabled),
                inspectorValueRow(
                    "Feather", binding, name: "Cutout Feather", unit: "%", decimals: 0,
                    min: 0, max: 100, quick: [0, 10, 25, 50],
                    read: { cut().feather * 100 },
                    ops: { part(CutoutPatch(feather: $0 / 100)) },
                    mixed: { binding.mixedVideo { $0.cutout?.feather } },
                    enabled: enabled),
                inspectorRow("Status", [readout]),
                inspectorButtonRow([analyze]),
            ])
    }
}
import AppKit

/// The Picture sub-tab's Behind Subject section (road map creator-jobs CO5, spec §11 CO-55),
/// right after Transform: one checkbox writing `video.behind_subject` — an end inside an action,
/// where the flag switches at the action's end (CO-52) — one undo step "Behind Subject", mixed
/// over a selection that disagrees, Reset writing false. With one clip selected and its flag on,
/// a note says when no cut-out clip is behind it at the playhead: the document's recipe there
/// names no subject group in the clip's cut (`BehindSubjectPlan.isCutBySubject`).
extension VideoPane {

    /// The section's gate: no nest open, and a selection with pixels holding no adjustment clip
    /// and no nest clip — the two kinds the core refuses the flag on (CO-52).
    var allBehindable: Bool {
        guard binding.document?.scope == nil else { return false }
        let clips = binding.clips
        return !clips.isEmpty && !binding.videoClips.isEmpty
            && !clips.contains { clip in
                if case .nest = clip.source { return true }
                return InspectorTab.isAdjustment(clip)
            }
    }

    func behindSubjectSection() -> InspectorSection {
        let binding = self.binding
        func on() -> Bool { binding.videoProps.behindSubject }
        func ops(_ value: Bool) -> [ReelOp] {
            binding.ops(video: VideoPatch(behindSubject: value))
        }
        func note() -> String? {
            guard binding.isSingle, let clip = binding.videoClips.first, on(),
                let document = binding.document, document.scope == nil,
                let recipe = document.project.recipe(at: document.playhead)
            else { return nil }
            return BehindSubjectPlan.isCutBySubject(clip: clip.id, in: recipe) == true
                ? nil : "No cut-out clip is behind it at the playhead."
        }
        return InspectorSection(
            id: "video.behind_subject", title: "Behind Subject",
            summary: { on() ? "on" : "off" },
            note: note,
            reset: { binding.apply("Behind Subject", ops(false)) },
            defaultExpanded: false,
            rows: [
                inspectorCheckRow(
                    "Behind subject", binding, name: "Behind Subject", read: on, ops: ops,
                    mixed: { binding.mixedVideo { $0.behindSubject } })
            ])
    }
}

/// The Shadow group, shared by the Video, Text and Shape panes because all
/// three write the SAME field — `video.shadow` (§4.3 lists it once under
/// Video and refers to it from the other two).
///
/// Every control writes a WHOLE `ShadowProps`: the patch replaces the object,
/// so each edit re-sends the other four values as they stand.
func inspectorShadowSection(_ binding: InspectorBinding) -> InspectorSection {
    func current() -> ShadowProps { binding.videoProps.shadow ?? ShadowProps() }
    func ops(_ next: ShadowProps) -> [ReelOp] { binding.ops(video: VideoPatch(shadow: .some(next))) }
    func on() -> Bool { binding.videoProps.shadow != nil }

    let toggle = inspectorCheckRow(
        "Drop shadow", binding, name: "Shadow",
        read: on,
        ops: { value in
            binding.ops(video: VideoPatch(shadow: value ? .some(ShadowProps()) : .some(nil)))
        },
        mixed: { binding.mixedVideo { $0.shadow != nil } })

    return InspectorSection(
        id: "video.shadow", title: "Shadow",
        summary: { on() ? String(format: "%.0f px", current().blur) : "off" },
        reset: { binding.apply("Shadow", video: VideoPatch(shadow: .some(nil))) },
        defaultExpanded: false,
        rows: [
            toggle,
            inspectorColorRow(
                "Color", binding, name: "Shadow Color", read: { current().color },
                ops: { color in
                    var s = current()
                    s.color = color
                    return ops(s)
                },
                mixed: { binding.mixedVideo { $0.shadow?.color } },
                enabled: on),
            inspectorValueRow(
                "Opacity", binding, name: "Shadow Opacity", unit: "%", decimals: 0, min: 0,
                max: 100, quick: [0, 25, 50, 75, 100],
                read: { current().opacity * 100 },
                ops: { value in
                    var s = current()
                    s.opacity = value / 100
                    return ops(s)
                },
                mixed: { binding.mixedVideo { $0.shadow?.opacity } },
                enabled: on),
            inspectorValueRow(
                "Blur", binding, name: "Shadow Blur", unit: " px", decimals: 0, min: 0, max: 200,
                quick: [0, 4, 8, 12, 24, 48],
                read: { current().blur },
                ops: { value in
                    var s = current()
                    s.blur = value
                    return ops(s)
                },
                mixed: { binding.mixedVideo { $0.shadow?.blur } },
                enabled: on),
            inspectorValueRow(
                "Angle", binding, name: "Shadow Angle", unit: "°", decimals: 0, min: 0, max: 360,
                quick: [0, 45, 90, 135, 180, 225, 270, 315],
                read: { current().angle },
                ops: { value in
                    var s = current()
                    s.angle = value
                    return ops(s)
                },
                mixed: { binding.mixedVideo { $0.shadow?.angle } },
                enabled: on),
            inspectorValueRow(
                "Distance", binding, name: "Shadow Distance", unit: " px", decimals: 0, min: 0,
                max: 200, quick: [0, 4, 8, 16, 32],
                read: { current().distance },
                ops: { value in
                    var s = current()
                    s.distance = value
                    return ops(s)
                },
                mixed: { binding.mixedVideo { $0.shadow?.distance } },
                enabled: on),
        ])
}

/// The colour as the model's RGBA, or nil when it already matches `current`.
///
/// **Pitfall:** the shared colour panel is continuous, so a drag inside it
/// calls a swatch's writer on every mouse-moved event — including with the
/// colour it already has. Without this guard the document would answer an
/// unchanged edit with a refusal beep on every one of them.
func changedRGBA(_ color: NSColor, from current: RGBA) -> RGBA? {
    let next = color.rgbaComponents
    guard next.count == current.count else { return next }
    for (a, b) in zip(next, current) where abs(a - b) > 0.001 { return next }
    return nil
}

