// app/Sources/EditorViewController+Cutout.swift — the preview's answer to a masks publish (road
// map creator-jobs CO2b, spec §11 CO-22 (d)). The compositor draws a cut-out clip uncut until its
// masks are cached (CO-6) and re-reads the pack on the marker's stat (CO-25); when a publish lands
// in this document's cache folder, a paused frame is recomposed by the one-tick round trip. A
// playing preview draws it on its next frame by itself, and the plan did not change, so nothing
// rebuilds.
//
// Clip ▸ Remove Background and the Background section's Analyze Now (road map creator-jobs CO3,
// spec §11 CO-30 (c), (e)), with their validator arm — the UI paths `analyze_cutout` and
// `set_video`'s `cutout` name.

import AppKit

extension EditorViewController {
    @objc func analysisDidPublish(_ note: Notification) {
        guard let document = document,
            // A picture's foreground masks too (spec §11 CO-107).
            [AnalysisKind.masks.rawValue, AnalysisKind.foreground.rawValue]
                .contains(note.userInfo?["kind"] as? String ?? ""),
            let folder = note.userInfo?["cacheDir"] as? String,
            document.intendedCacheDirectory?.standardizedFileURL.path == folder
        else { return }
        playback.refreshPausedFrame()
    }

    /// The selected clips in the open scope that can be cut out (CO-30 (e)).
    private var cutoutTargets: [ClipSnapshot] {
        guard let document = document else { return [] }
        let snapshot = document.editedProject.snapshot
        return selectedClips.filter { CutoutStatus.canCutOut($0, in: snapshot) }
    }

    /// Clip ▸ Remove Background: every target cut out → all off; otherwise the ones without a
    /// cutout on, each cut-out clip's own values kept. One undo step, one base `set_video` per
    /// clip as Clip ▸ Motion ▸ writes.
    @objc func toggleRemoveBackground(_ sender: Any?) {
        guard let document = document else {
            NSSound.beep()
            return
        }
        let ops = CutoutStatus.toggleOps(selectedClips, in: document.editedProject.snapshot)
        guard !ops.isEmpty else {
            NSSound.beep()
            return
        }
        document.applyEdit("Remove Background", ops)
    }

    /// The Background section's Analyze Now: the wants made again, then a failed run retried
    /// (`ProjectDocument.analyzeMasksNow`).
    @objc func analyzeCutoutNow(_ sender: Any?) {
        guard let document = document else {
            NSSound.beep()
            return
        }
        document.analyzeMasksNow()
    }

    /// The half of `validateUserInterfaceItem` this file owns; nil is "not mine". Remove
    /// Background's checkmark is on, mixed or off as every, some or none of the targets is cut
    /// out.
    func validateCutoutAction(_ action: Selector, item: NSValidatedUserInterfaceItem?) -> Bool? {
        switch action {
        case #selector(toggleRemoveBackground(_:)):
            guard let document = document else { return false }
            (item as? NSMenuItem)?.state = CutoutStatus.menuState(
                selectedClips, in: document.editedProject.snapshot)
            return !cutoutTargets.isEmpty
        case #selector(analyzeCutoutNow(_:)):
            guard let document = document else { return false }
            return cutoutTargets.filter { $0.video?.cutout != nil }.contains { clip in
                switch CutoutStatus.status(of: clip.id, in: document).state {
                case .analyzing, .failed: return true
                default: return false
                }
            }
        default:
            return nil
        }
    }
}
import AppKit

// Where a cut-out clip's masks stand (road map creator-jobs CO3, spec §11 CO-30, CO-31; a
// picture's, CO10b, CO-108):
// the Background section's Status and Analyze Now, Clip ▸ Remove Background's targets, toggle
// and checkmark, and `analyze_cutout`'s answer, centroid included. Names no `rc_*` (CJ-8 (l)):
// the plans and snapshots come through `ReelProject`, the windows and the need rule are
// `CutoutWants`' (CO-22), the coverage the store's, the runs the lane's.

/// A clip's cutout state (CO-30 (c), CO-31 (a)).
enum CutoutState: Equatable {
    case off
    case noPicture
    /// 0…1, CO-31 (a)'s progress.
    case analyzing(Double)
    case ready
    case noPerson
    /// A picture cut by its foreground whose mask found none (spec §11 CO-108).
    case noSubject
    /// The reason, in the Status read-out's words.
    case failed(String)

    /// Whether `analyze_cutout` stops waiting on it.
    var isSettled: Bool {
        if case .analyzing = self { return false }
        return true
    }

    /// The same state, a progress apart aside.
    func sameKind(as other: CutoutState) -> Bool {
        switch (self, other) {
        case (.analyzing, .analyzing): return true
        default: return self == other
        }
    }
}

/// One clip's status (CO-31 (a)).
struct CutoutClipStatus: Equatable {
    let clip: UInt32
    let media: UInt32?
    let state: CutoutState
    /// The needed grid indices of the clip's windows, merged.
    let frames: Int
    /// Of those, the ones the store covers for the analysis's stamp.
    let covered: Int
    let subjectFound: Bool
    /// The tool's sentence when failed.
    let error: String?
}

enum CutoutStatus {

    /// What a status was read from: the media, the needed ranges, the stored coverage and the
    /// pack's file, and the document's lane owner — what the read-out's tick recomputes the
    /// progress from and `analyze_cutout` reads the centroid from, off main.
    struct Detail {
        let status: CutoutClipStatus
        let media: MediaSnapshot?
        let need: [ClosedRange<Int>]
        let coverage: [ClosedRange<Int>]
        let pack: URL?
        let owner: Int?
        /// The document's cache folder, when the status read one.
        let cacheDir: URL?
        /// The analysis kind of the clip's masks (`CutoutWants.kind(of:)`, CO-106).
        var kind: AnalysisKind = .masks
    }

    // MARK: - Which clips

    /// A media or still clip of a video file with pictures (CO-30 (a)), or an image clip of a
    /// picture (CO-108).
    static func canCutOut(_ clip: ClipSnapshot, in snapshot: ProjectSnapshot) -> Bool {
        switch clip.source {
        case .media, .still:
            guard let media = snapshot.media(for: clip) else { return false }
            return media.kind == .video && media.hasVideo
        case .image:
            return snapshot.media(for: clip)?.kind == .image
        default:
            return false
        }
    }

    /// Clip ▸ Remove Background's edit (CO-30 (e)): with every clip that can be cut out already
    /// cut out, a null to each; otherwise a whole default cutout to each one without. One base
    /// `set_video` per clip.
    static func toggleOps(_ clips: [ClipSnapshot], in snapshot: ProjectSnapshot) -> [ReelOp] {
        let targets = clips.filter { canCutOut($0, in: snapshot) }
        guard !targets.isEmpty else { return [] }
        if targets.allSatisfy({ $0.video?.cutout != nil }) {
            return targets.map { .setVideo(clips: [$0.id], patch: VideoPatch(cutout: .some(nil))) }
        }
        return targets.filter { $0.video?.cutout == nil }.map {
            .setVideo(clips: [$0.id], patch: VideoPatch(cutout: .some(CutoutProps())))
        }
    }

    /// The menu item's checkmark: on when every clip that can be cut out is, mixed when some
    /// are, off when none is (or none can be).
    static func menuState(_ clips: [ClipSnapshot], in snapshot: ProjectSnapshot)
        -> NSControl.StateValue
    {
        let targets = clips.filter { canCutOut($0, in: snapshot) }
        let on = targets.filter { $0.video?.cutout != nil }.count
        if on == 0 { return .off }
        return on == targets.count ? .on : .mixed
    }

    // MARK: - The status (CO-31 (a))

    /// `clip`'s status in `document`. Main thread.
    static func status(of clip: UInt32, in document: ProjectDocument) -> CutoutClipStatus {
        detail(of: clip, in: document).status
    }

    /// `clip`'s status and what it was read from. Main thread.
    static func detail(of clip: UInt32, in document: ProjectDocument) -> Detail {
        let handles = document.scope == nil
        let folder = cacheDir.standardizedFileURL
        return AnalysisLane.shared.requests(of: owner).filter {
            $0.kind == kind && $0.media.id == media && $0.cacheDir.standardizedFileURL == folder
        }
    }

    /// The first of `requests` started and not ended.
    static func runningRequest(_ requests: [AnalysisRequest]) -> AnalysisRequest? {
        requests.first { request in
            guard let run = AnalysisLane.shared.run(of: request) else { return false }
            return run.startedAt != nil && run.outcome == nil
        }
    }

    /// The Status read-out's words (CO-30 (c)).
    static func words(_ state: CutoutState) -> String {
        switch state {
        case .off: return "Off"
        case .noPicture: return "No picture to analyze"
        case .analyzing(let progress):
            return "Analyzing \(min(99, max(0, Int((progress * 100).rounded(.down))))) %"
        case .ready: return "Ready"
        case .noPerson: return "No person found"
        case .noSubject: return "No subject found"
        case .failed(let why): return "Failed: \(why)"
        }
    }

    // MARK: - Progress (CO-31 (a))

    /// `(C_out + f · R_in) / N`: N the needed indices, R_in those inside `running`'s ranges,
    /// C_out the covered needed indices outside them; with no running request, C / N. Pure,
    /// 0…1.
    static func progress(
        need: [ClosedRange<Int>], covered: [ClosedRange<Int>], running: [ClosedRange<Int>]?,
        fraction: Double
    ) -> Double {
        let need = AnalysisStore.merged(need)
        let total = count(need)
        guard total > 0 else { return 0 }
        let coveredNeed = intersect(need, covered)
        let c = count(coveredNeed)
        guard let running else { return Double(c) / Double(total) }
        let rIn = count(intersect(need, running))
        let cOut = c - count(intersect(coveredNeed, running))
        let f = min(1, max(0, fraction))
        return min(1, max(0, (Double(cOut) + f * Double(rIn)) / Double(total)))
    }

    /// How many indices `ranges` hold, merged first.
    static func count(_ ranges: [ClosedRange<Int>]) -> Int {
        AnalysisStore.merged(ranges).reduce(0) { $0 + $1.count }
    }

    /// The indices both hold, merged.
    static func intersect(_ a: [ClosedRange<Int>], _ b: [ClosedRange<Int>])
        -> [ClosedRange<Int>]
    {
        let a = AnalysisStore.merged(a), b = AnalysisStore.merged(b)
        var out: [ClosedRange<Int>] = []
        var i = 0, j = 0
            let reading = snapshot.output == .hlg
                ? KeyReading.common(keyed.map { KeyReading.of(media: $0, url: urls[$0.id]) })
                : .unlift
            let frame = Exporter.renderFrame(
                project: project, urls: urls, at: time, maxWidth: nil, graphics: graphics)
            let picked = frame.flatMap {
                CanvasEyedropperSession.keyColor(
                    at: target, in: $0, canvas: snapshot, reading: reading)
            }
            DispatchQueue.main.async { self?.chromaKeySampled(picked, session: session) }
        }
    }

    /// Back on the main thread with the sampled colour.
    ///
    /// The commit goes through the BINDING rather than straight to the
    /// document, because the binding is the one place that knows an edit made
    /// while the playhead sits inside an action belongs to that action's end
    /// state rather than to the clip's base props (§4.3) — and `applyGrouped`
    /// is its off-event door, which this is.
    private func chromaKeySampled(_ color: RGBA?, session: CanvasEyedropperSession) {
        guard let inspector = inspector, let color = color else {
            // A frame that would not compose, or a pixel with no colour in
            // it. Nothing to say beyond "that did not work".
            NSSound.beep()
            return
        }
        let binding = inspector.binding
        guard binding.videoClips.map({ $0.id }) == session.clips else {
            // The selection moved while the frame was composing. Dropped
            // rather than applied to a clip the user never aimed at.
            NSSound.beep()
            return
        }
        binding.applyGrouped(
            "Chroma Key",
            binding.ops(video: VideoPatch(chroma: .some(session.chroma(picked: color)))))
    }
}

extension CanvasEyedropperSession {
    /// The chroma key the eyedropper stores for a pick at `point`: the
    /// frame's colour there, read at its code values (`FrameWriter.pickable`)
    /// — and in an HLG project read through the keyed clips' `reading`, so the
    /// stored key is the SDR colour an SDR project shows and keys through the
    /// shader's same reading in both outputs: the un-lift to the Rec. 709
    /// colour it is (spec §11 HD-13 (h)) by default, GR-15's HDR→SDR arm for
    /// an HLG or PQ source (HD-19 (c)).
    static func keyColor(
        at point: CGPoint, in frame: CGImage, canvas: CanvasSnapshot,
        reading: KeyReading = .unlift
    ) -> RGBA? {
        let picked = color(at: point, in: FrameWriter.pickable(frame), canvas: canvas)
        guard canvas.output == .hlg else { return picked }
        return picked.map(reading.pick)
    }
}

// MARK: - The overlays

/// What every modal canvas mode's view shares: a transparent sheet over the
/// whole picture that holds first responder so Esc reaches it, wears the
/// crosshair, and says how to get back out in a pill. `CanvasPickOverlay`
/// (a click) and `CanvasRegionView` (a drag) subclass it for the gesture and
/// the state each mode carries; `dismissCanvasMode` tears any of them down.
class CanvasModeOverlay: NSView, CanvasModalMode {
    var onCancel: (() -> Void)?

    static let hintTop: CGFloat = 10
    private static let hintPadding: CGFloat = 9

    override init(frame frameRect: NSRect) {
        super.init(frame: frameRect)
        wantsLayer = true
    }

    var didMove = false

    var op: ReelOp {
        let values = [canvasRound(unit.x), canvasRound(unit.y)]
        switch endpoint {
        case .from: return .setShape(clips: [clip], patch: ShapePatch(from: values))
        case .to: return .setShape(clips: [clip], patch: ShapePatch(to: values))
        }
    }

    /// `unit` comes from `CanvasLayerBox.endpointUnit`, which owns the
    /// rotation and the box maths.
    mutating func update(unit: CGPoint) {
        self.unit = unit
        didMove = true
    }
}

